@@ -57,0 +59,20 @@
+    // Apply contrast. The allowed values are from 0.0 to 1.0. On Windows a
+    // user can tweak this setting using the ClearType tuner but most don't
+    // so we just hard-code a default. Brighter colors tend to bloom outward
+    // and make the stems look wider so we tone it down the brighter the
+    // source is. P.S. Can't name this contrast since that identifier is
+    // reserved on macOS.
+    float3 cntrst = float3(0.75);
+
+    // When drawing white text on a black background the glyph will appear
+    // heavier even with no contrast applied.
+    float3 w = float3(0.21, 0.72, 0.07);
+    float srcLightness = dot(c.rgb, w);
+    float dstLightness = dot(dstClr.rgb, w);
+    cntrst = cntrst * (1.0 - clamp(srcLightness - dstLightness, 0.0, 1.0));
+
+    glyphClr.rgb = glyphClr.rgb + ((one - glyphClr.rgb) * cntrst * glyphClr.rgb);
+
+    // glyphClr.a defined as average texel coverage of glyph
+    glyphClr.a = dot(glyphClr.rgb, third);
+
@@ -103,1 +125,7 @@
-    dstClr = pow(dstClr, float4(gamma.y, gamma.y, gamma.y, gamma.y));
+    // Linearize the destination
